/* From Uiverse.io by mrhyddenn - Tags: loader */
.__UIV_SCOPE__ .mover {
  background: rgba(248, 25, 25, 0.979);
  height: 10px;
  width: 80px;
  border-radius: 10px;
  position: relative;
  animation: mover5 2s ease-in-out infinite;
}

.__UIV_SCOPE__ .mover::before,
.__UIV_SCOPE__ .mover::after {
  content: '';
  position: absolute;
  height: 10px;
  border-radius: 10px;
  left: 20px;
  animation: mover5 2s ease-in-out infinite;
}

.__UIV_SCOPE__ .mover::before {
  background: rgb(201, 1, 1);
  top: 20px;
  width: 50px;
}

.__UIV_SCOPE__ .mover::after {
  background: rgb(255, 116, 106);
  top: -20px;
  width: 60px;
}

@keyframes mover5 {
  0% {
    transform: translateX(30px) scale(1);
  }

  50% {
    transform: translateX(-30px) scale(1.1);
  }

  100% {
    transform: translateX(30px) scale(1);
  }
}
